import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.logging.Logger;
import java.lang.reflect.*;
import org.bukkit.*;
import org.bukkit.command.*;
import net.md_5.bungee.api.chat.*;
import com.denizenscript.denizen.scripts.commands.server.AnnounceCommand;
import com.denizenscript.denizencore.*;
import com.denizenscript.denizencore.scripts.*;
import com.denizenscript.denizencore.scripts.containers.core.TaskScriptContainer;
import com.denizenscript.denizencore.tags.TagContext;
import com.denizenscript.denizencore.utilities.YamlConfiguration;

public class Probe {
    static final List<String> messages=new ArrayList<>();
    static class LocalContext extends TagContext {
        private final ScriptEntryData data;
        LocalContext(ScriptEntry entry, ScriptEntryData data) { super(entry); this.data=data; }
        public ScriptEntryData getScriptEntryData() { return data; }
    }
    static class EntryData extends ScriptEntryData {
        public void transferDataFrom(ScriptEntryData source) {}
        public TagContext getTagContext() { return new LocalContext(null,this); }
        public YamlConfiguration save() { return new YamlConfiguration(); }
        public void load(YamlConfiguration ignored) {}
    }
    @SuppressWarnings("unchecked")
    static <T> T proxy(Class<T> type, InvocationHandler f) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},f);
    }
    static Object defaultValue(Method method) {
        if (method.getReturnType()==boolean.class) return false;
        if (method.getReturnType()==int.class) return 0;
        if (method.getReturnType()==long.class) return 0L;
        if (method.getReturnType()==String.class) return "";
        return null;
    }
    public static void main(String[] args) throws Exception {
        ConsoleCommandSender.Spigot output=new ConsoleCommandSender.Spigot() {
            @Override public void sendMessage(BaseComponent... payload) {
                messages.add(TextComponent.toPlainText(payload));
            }
            @Override public void sendMessage(BaseComponent payload) { sendMessage(new BaseComponent[]{payload}); }
        };
        var console=proxy(ConsoleCommandSender.class,(o,m,a)->m.getName().equals("spigot") ? output : defaultValue(m));
        var server=proxy(Server.class,(o,m,a)->switch(m.getName()) {
            case "getConsoleSender" -> console;
            case "getLogger" -> Logger.getLogger("corpus");
            case "getName","getVersion","getBukkitVersion" -> "corpus host fixture";
            case "getOnlinePlayers" -> List.of();
            default -> defaultValue(m);
        });
        Bukkit.setServer(server);
        var platform=proxy(DenizenImplementation.class,(o,m,a)->switch(m.getName()) {
            case "getDataFolder","getScriptFolder" -> new File(".");
            case "getImplementationName","getImplementationVersion" -> "corpus console host";
            case "getEmptyScriptEntryData" -> new EntryData();
            case "getTagContext" -> new LocalContext(a!=null && a[0] instanceof ScriptEntry entry ? entry : null,new EntryData());
            case "cleanseLogString" -> a[0];
            case "canReadFile","canWriteToFile" -> true;
            default -> defaultValue(m);
        });
        DenizenCore.init(platform);
        DenizenCore.commandRegistry.registerCommand(AnnounceCommand.class);
        var document=YamlConfiguration.load(Files.readString(Path.of("hello.dsc")));
        ScriptRegistry.buildCoreYamlScriptContainers(List.of(document));
        TaskScriptContainer task=ScriptRegistry.getScriptContainer("hello_world");
        if (task==null) throw new IllegalStateException("Original task was not loaded");
        task.run();
        if (!messages.equals(List.of("Hello, World!"))) throw new AssertionError(messages);
        System.out.println("Observed console: "+messages.get(0));
    }
}
